  if (offset >= 0x6c52 && offset < 0x6c52 + sizeof(BZ01_HOOK_TICK)) return BZ01_HOOK_TICK[offset - 0x6c52];
  if (offset >= 0x5df4 && offset < 0x5df4 + sizeof(BZ01_HOOK_BOOT)) return BZ01_HOOK_BOOT[offset - 0x5df4];
  if (offset >= 0x2682 && offset < 0x2682 + sizeof(BZ01_HOOK_TRIM_PRESET_1)) return BZ01_HOOK_TRIM_PRESET_1[offset - 0x2682];
  if (offset >= 0x279a && offset < 0x279a + sizeof(BZ01_HOOK_TRIM_PRESET_2)) return BZ01_HOOK_TRIM_PRESET_2[offset - 0x279a];
  if (offset >= 0x28b2 && offset < 0x28b2 + sizeof(BZ01_HOOK_TRIM_PRESET_3)) return BZ01_HOOK_TRIM_PRESET_3[offset - 0x28b2];
  if (offset >= 0x619e && offset < 0x619e + sizeof(BZ01_HOOK_TRIM_DIRECT)) return BZ01_HOOK_TRIM_DIRECT[offset - 0x619e];
  if (offset >= 0xe10 && offset < 0xe10 + sizeof(BZ01_HOOK_TRIM_TX)) return BZ01_HOOK_TRIM_TX[offset - 0xe10];
  if (offset >= 0x1b8c && offset < 0x1b8c + sizeof(BZ01_HOOK_TRIM_GPIO)) return BZ01_HOOK_TRIM_GPIO[offset - 0x1b8c];
  if (offset >= 0x30d0 && offset < 0x30d0 + sizeof(BZ01_HOOK_TRIM_NATIVE)) return BZ01_HOOK_TRIM_NATIVE[offset - 0x30d0];
  if (offset >= 0x53ae && offset < 0x53ae + sizeof(BZ01_HOOK_TRIM_UART)) return BZ01_HOOK_TRIM_UART[offset - 0x53ae];
  if (offset >= 0x5e36 && offset < 0x5e36 + sizeof(BZ01_HOOK_TRIM_STARTUP)) return BZ01_HOOK_TRIM_STARTUP[offset - 0x5e36];
  if (offset >= 0x5e3e && offset < 0x5e3e + sizeof(BZ01_HOOK_TRIM_SELECTOR)) return BZ01_HOOK_TRIM_SELECTOR[offset - 0x5e3e];
  if (offset >= 0x5e84 && offset < 0x5e84 + sizeof(BZ01_HOOK_TRIM_FOREGROUND)) return BZ01_HOOK_TRIM_FOREGROUND[offset - 0x5e84];
  if (offset >= 0x3fec && offset < 0x3fec + sizeof(BZ01_HOOK_BUZZER_TIMER)) return BZ01_HOOK_BUZZER_TIMER[offset - 0x3fec];
  if (offset >= 0x7810 && offset < 0x7810 + sizeof(BZ01_CANDIDATE)) return BZ01_CANDIDATE[offset - 0x7810];
  if (offset >= 0xd3e0 && offset < 0xd3e0 + sizeof(BZ01_DESCRIPTOR)) return BZ01_DESCRIPTOR[offset - 0xd3e0];
